import React, { useState } from "react";
import { Box, Typography, Button, TextField, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Dialog, DialogTitle, DialogContent, DialogActions } from "@mui/material";
import { Add, Edit, Delete } from "@mui/icons-material";

const ManageElections = () => {
  const [elections, setElections] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [currentElection, setCurrentElection] = useState({ id: null, name: "", startDate: "", endDate: "" });

  const handleOpenDialog = (election = { id: null, name: "", startDate: "", endDate: "" }) => {
    setCurrentElection(election);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setCurrentElection({ id: null, name: "", startDate: "", endDate: "" });
  };

  const handleSaveElection = () => {
    if (currentElection.id === null) {
      // Add new election
      setElections([...elections, { ...currentElection, id: elections.length + 1 }]);
    } else {
      // Update existing election
      setElections(elections.map((election) =>
        election.id === currentElection.id ? currentElection : election
      ));
    }
    handleCloseDialog();
  };

  const handleDeleteElection = (id) => {
    setElections(elections.filter((election) => election.id !== id));
  };

  return (
    <Box sx={{ p: 4 }}>
      <Typography variant="h4" fontWeight="bold" mb={4}>
        Manage Elections
      </Typography>

      <Button
        variant="contained"
        startIcon={<Add />}
        onClick={() => handleOpenDialog()}
        sx={{ mb: 4 }}
      >
        Create New Election
      </Button>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Election Name</TableCell>
              <TableCell>Start Date</TableCell>
              <TableCell>End Date</TableCell>
              <TableCell>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {elections.map((election) => (
              <TableRow key={election.id}>
                <TableCell>{election.name}</TableCell>
                <TableCell>{election.startDate}</TableCell>
                <TableCell>{election.endDate}</TableCell>
                <TableCell>
                  <Button
                    startIcon={<Edit />}
                    onClick={() => handleOpenDialog(election)}
                    sx={{ mr: 1 }}
                  >
                    Edit
                  </Button>
                  <Button
                    startIcon={<Delete />}
                    onClick={() => handleDeleteElection(election.id)}
                    color="error"
                  >
                    Delete
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Dialog for adding/editing elections */}
      <Dialog open={openDialog} onClose={handleCloseDialog}>
        <DialogTitle>{currentElection.id ? "Edit Election" : "Create New Election"}</DialogTitle>
        <DialogContent>
          <TextField
            label="Election Name"
            fullWidth
            value={currentElection.name}
            onChange={(e) => setCurrentElection({ ...currentElection, name: e.target.value })}
            sx={{ mt: 2 }}
          />
          <TextField
            label="Start Date"
            type="date"
            fullWidth
            InputLabelProps={{ shrink: true }}
            value={currentElection.startDate}
            onChange={(e) => setCurrentElection({ ...currentElection, startDate: e.target.value })}
            sx={{ mt: 2 }}
          />
          <TextField
            label="End Date"
            type="date"
            fullWidth
            InputLabelProps={{ shrink: true }}
            value={currentElection.endDate}
            onChange={(e) => setCurrentElection({ ...currentElection, endDate: e.target.value })}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button onClick={handleSaveElection} variant="contained">
            Save
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ManageElections;
